import dataclasses
from typing import List, Optional

@dataclasses.dataclass
class TranscriptionRequest:
    audio_file_url: str
    language: str
    diarization_enabled: bool = False
    word_timestamps_enabled: bool = False

@dataclasses.dataclass
class TranscriptionResponse:
    job_id: str
    status: str
    transcript_url: Optional[str] = None
    diarization_result_url: Optional[str] = None
    word_timestamps_url: Optional[str] = None

@dataclasses.dataclass
class TranscriptSegment:
    id: int
    start: str
    end: str
    text: str
    speaker: Optional[str] = None

@dataclasses.dataclass
class WordTimestamp:
    word: str
    start: str
    end: str

@dataclasses.dataclass
class DiarizationResult:
    segments: List[TranscriptSegment]

@dataclasses.dataclass
class TimestampedTranscript:
    words: List[WordTimestamp]

import os
from azure.cognitiveservices.speech import SpeechConfig, SpeechRecognizer, AudioConfig
from azure.storage.blob import BlobServiceClient


class AzureSpeechClient:
    def __init__(self):
        self.speech_key = os.environ.get("AZURE_SPEECH_KEY")
        self.service_region = os.environ.get("AZURE_SPEECH_REGION")
        self.blob_connection_string = os.environ.get("AZURE_STORAGE_CONNECTION_STRING")

        if not self.speech_key or not self.service_region:
            raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables must be set.")

        self.speech_config = SpeechConfig(subscription=self.speech_key, region=self.service_region)

    def get_blob_service_client(self):
        if not self.blob_connection_string:
            raise ValueError("AZURE_STORAGE_CONNECTION_STRING environment variable must be set for blob operations.")
        return BlobServiceClient.from_connection_string(self.blob_connection_string)

    def get_speech_config(self):
        return self.speech_config

import os
import googleapiclient.discovery
from speech_models import TranscriptSegment
from typing import List, Dict, Any

def moderate_transcript_text(segments: List[TranscriptSegment]) -> List[Dict[str, Any]]:
    client = googleapiclient.discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=os.environ.get("PERSPECTIVE_API_KEY"),
        discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
        static_discovery=False
    )

    moderated_results = []
    for segment in segments:
        analyze_request = {
            'comment': {'text': segment.text},
            'requestedAttributes': {
                'TOXICITY': {},
                'SEVERE_TOXICITY': {},
                'IDENTITY_ATTACK': {},
                'INSULT': {},
                'PROFANITY': {},
                'THREAT': {},
            }
        }

        response = client.comments().analyze(body=analyze_request).execute()

        attribute_scores = {
            attribute: scores['summaryScore']['value']
            for attribute, scores in response['attributeScores'].items()
        }

        moderated_results.append({
            "segment_id": segment.id,
            "text": segment.text,
            "moderation_scores": attribute_scores
        })
    return moderated_results
